const mails = await api.get("/mails", {});
const refundMails = mails.items.filter(m => /환불/.test(m.subject + " " + m.body + " " + m.label));
const custIds = [...new Set(refundMails.map(m => m.customer_id).filter(Boolean))];
const customers = await Promise.all(custIds.map(id => api.get(`/customers/${id}`)));
const tiers = [...new Set((await api.get("/customers", {})).items.map(c => c.tier))];
return {
  mailCount: mails.count,
  refundMailCount: refundMails.length,
  refundMails: refundMails.map(m => ({id: m.id, customer_id: m.customer_id, contact_id: m.contact_id, subject: m.subject, label: m.label})),
  customers: customers.map(c => ({id: c.id, name: c.name, tier: c.tier})),
  tiers
};

